alter table public.operacion_control_comercial add column if not exists cancelacion_justificativo text,add column if not exists cancelacion_evidencia_url text,add column if not exists cancelacion_solicitada_por uuid references public.profiles(id) on delete set null,add column if not exists cancelacion_revision_estado text default 'PENDIENTE_REVISION',add column if not exists cancelacion_revision_por uuid references public.profiles(id) on delete set null,add column if not exists cancelacion_revision_fecha timestamptz,add column if not exists cancelacion_revision_observaciones text;
create table if not exists public.cancelaciones_contrato(id uuid primary key default gen_random_uuid(),operacion_id uuid not null references public.operaciones(id) on delete restrict,contrato_id uuid references public.contratos(id) on delete set null,solicitada_por uuid not null references public.profiles(id) on delete restrict,motivo text not null,justificativo text not null,evidencia_url text,estado_revision text not null default 'PENDIENTE',revisada_por uuid references public.profiles(id) on delete set null,revisada_at timestamptz,observaciones_revision text,importe_comision_considerado numeric(24,8) not null default 0,importe_comision_devuelto numeric(24,8) not null default 0,moneda_id integer references public.monedas(id),devolucion_estado text not null default 'NO_APLICA',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint cancelacion_revision_estado_chk check(estado_revision in ('PENDIENTE','APROBADA','RECHAZADA')),constraint cancelacion_devolucion_estado_chk check(devolucion_estado in ('NO_APLICA','PENDIENTE','REGISTRADA','ORDENADA','CONFIRMADA','NO_PROCEDE')),constraint cancelacion_justificativo_chk check(length(trim(justificativo))>=10));
alter table public.cancelaciones_contrato enable row level security;